      css.push(`.base-fill{fill:${baseFillColor}}`);
      css.push(`.base-bg-path{fill:${baseBgColor}}`);
      css.push(`.base-border-path{fill:${baseStrokeColor}}`);
      css.push(`.base-fill{fill:${baseStrokeColor}}`);
