              let minY = Infinity;
              let maxX = -Infinity;
              let maxY = -Infinity;
              for (let i = 0; i < local.length; i += 2) {
                  const px = base.x + local[i];
                  const py = base.y + local[i + 1];
                  hitPoly[i] = px;
                  hitPoly[i + 1] = py;
                  if (px < minX)
                      minX = px;
                  if (py < minY)
                      minY = py;
                  if (px > maxX)
                      maxX = px;
                  if (py > maxY)
                      maxY = py;
              }
              // 组头部可能伸到框外（position='outside'），它自己也要能点中，
              // 所以单独算一份头部四边形，并把包围盒扩到二者的并集。
