                      if (headPoly[i + 1] < minY)
                          minY = headPoly[i + 1];
                      if (headPoly[i] > maxX)
                          maxX = headPoly[i];
                      if (headPoly[i + 1] > maxY)
                          maxY = headPoly[i + 1];
