                  const s = vnode.data?.start;
                  const e = vnode.data?.end;
                  minX = Math.min(s?.x ?? 0, e?.x ?? 0);
                  minY = Math.min(s?.y ?? 0, e?.y ?? 0);
                  maxX = Math.max(s?.x ?? 0, e?.x ?? 0);
                  maxY = Math.max(s?.y ?? 0, e?.y ?? 0);
