          text: t('未绑定集群'),
          anchorX: vnode.position.x,
          anchorY: vnode.position.y,
          mat,
          localX: centerX,
          localY: 0,
          boxWidth: 0,
          boxHeight: textHeight,
          align: 'left',
          fontSize,
          glyphPx,
