      const glyphPx = pickGlyphSize(fontSize, view.state.dpr, view.worldPerPixel, glyph.renderSizeCap);
      const isAttached = !!vnode.attach;
      /** 绘制原点：线上文本可能被 focus 固定 / hover 跟随 / 补偿回退所覆盖 */
      const originX = frame ? frame.origin.x : vnode.position.x;
      const originY = frame ? frame.origin.y : vnode.position.y;
      const fill = isDark ? '#FFFFFF' : getStylesVal(styles.fill) || '#000000';
      // 亮色下 div 有 4 向 1px 白色 text-shadow；暗色 none
      const outlineColor = isDark ? COLOR_TRANSPARENT : 0xffffffff;
      const outlineScale = isDark ? 0 : 1;
