  const GRID_VS = `${COMMON}
out vec2 vWorld;
void main() {
  vec2 p;
  if (gl_VertexID == 0) p = vec2(-1.0, -3.0);
  else if (gl_VertexID == 1) p = vec2(-1.0, 1.0);
  else p = vec2(3.0, 1.0);
  gl_Position = vec4(p, 0.0, 1.0);
  vWorld = clipToWorld(p);
}
`;
  const GRID_FS = `${FRAG_HEAD}
in vec2 vWorld;
uniform vec4  uEntire;
uniform vec4  uQuarter;
uniform vec4  uBackground;
uniform float uStrokeWidth;
uniform float uHasQuarter;
uniform float uDpr;

const float ISO_SLOPE = 0.578125;
const float D3_PERIOD = 74.0;
const float D2_PERIOD = 90.0;

float lineDist(float phase, float target, float period, float gradLen) {
  float t = (phase - target) / period;
  return abs(fract(t + 0.5) - 0.5) * period / gradLen;
}
float coverage(float d, float halfW, float aa) {
  return 1.0 - smoothstep(halfW - aa, halfW + aa, d);
}

void main() {
  // 对齐老版 SVG <pattern>：与 GRID_WGSL 逐行等价，改动须两处同步。
  // 所有网格线始终画在原位（不按缩放抽线），线细于 1 物理像素时只变淡；
  // CPU 参考实现见 renders/subpixel-stroke.ts 的 gridStrokeAlpha。
  float dpr = uDpr > 0.0 ? uDpr : 1.0;
  float devPx = max(uWorldPerPx / dpr, 1e-6);
  float halfW = max(uStrokeWidth, devPx) * 0.5;
  float subpixel = clamp(uStrokeWidth / devPx, ${MIN_SUBPIXEL_GRID_ALPHA.toFixed(2)}, 1.0);
  float aa = devPx * 0.5;

  float entireA = 0.0;
  float quarterA = 0.0;

  if (uIsoMode > 0.5) {
    float gradLen = sqrt(1.0 + ISO_SLOPE * ISO_SLOPE);
    float a = vWorld.y - ISO_SLOPE * vWorld.x;
    float b = vWorld.y + ISO_SLOPE * vWorld.x;
    entireA = max(coverage(lineDist(a, 0.0, D3_PERIOD, gradLen), halfW, aa),
                  coverage(lineDist(b, 0.0, D3_PERIOD, gradLen), halfW, aa));
    if (uHasQuarter > 0.5) {
      quarterA = max(coverage(lineDist(a, 37.0, D3_PERIOD, gradLen), halfW, aa),
                     coverage(lineDist(b, 37.0, D3_PERIOD, gradLen), halfW, aa));
    }
  } else {
    entireA = max(coverage(lineDist(vWorld.x, 0.0, D2_PERIOD, 1.0), halfW, aa),
                  coverage(lineDist(vWorld.y, 0.0, D2_PERIOD, 1.0), halfW, aa));
    if (uHasQuarter > 0.5) {
      quarterA = max(coverage(lineDist(vWorld.x, 45.0, D2_PERIOD, 1.0), halfW, aa),
                     coverage(lineDist(vWorld.y, 45.0, D2_PERIOD, 1.0), halfW, aa));
    }
  }

  // subpixel 一并乘入：亚像素时线条变淡而非糊宽
  // 顺序 = z 序：quarter（sence 层）→ entire（grid 层）
  vec4 col = uBackground;
  col = mix(col, uQuarter, quarterA * uQuarter.a * subpixel);
  col = mix(col, uEntire,  entireA  * uEntire.a  * subpixel);
  fragColor = vec4(col.rgb, 1.0);
}
`;
